import { test, expect } from '@playwright/test';

test.describe('User Mention in Comment', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/comments');
  });

  test('should successfully mention another user in a comment', async ({ page }) => {
    // Setup: Navigate to comment section
    await page.goto('/comments');

    // Setup: Get user input field by role
    const commentInput = page.getByRole('textbox', { name: /comment/i });
    await expect(commentInput).toBeVisible();

    // Setup: Get submit button by role
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Action: Type comment with mention
    await commentInput.fill('Hey @johnDoe, can you review this?');

    // Action: Verify mention suggestion appears
    const mentionSuggestion = page.getByText('johnDoe');
    await expect(mentionSuggestion).toBeVisible();

    // Action: Select mention from suggestion
    await mentionSuggestion.click();

    // Action: Verify mention is correctly formatted
    await expect(commentInput).toContainText('@johnDoe');

    // Action: Submit comment
    await submitButton.click();

    // Verification: Comment is posted
    const postedComment = page.getByText('Hey @johnDoe, can you review this?');
    await expect(postedComment).toBeVisible();

    // Verification: Mention is clickable and displays user info
    const mentionLink = page.getByText('@johnDoe');
    await expect(mentionLink).toBeVisible();
    await expect(mentionLink).toHaveAttribute('href', '/users/johnDoe');

    // Verification: User profile card appears on hover
    await mentionLink.hover();
    const profileCard = page.getByText('John Doe');
    await expect(profileCard).toBeVisible();
  });

  test('should handle invalid mention format and prevent submission', async ({ page }) => {
    // Setup: Navigate to comment section
    await page.goto('/comments');

    // Setup: Get comment input field by role
    const commentInput = page.getByRole('textbox', { name: /comment/i });
    await expect(commentInput).toBeVisible();

    // Setup: Get submit button by role
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Action: Type invalid mention format
    await commentInput.fill('Hey @invalid-mention');

    // Action: Verify no mention suggestion appears
    const mentionSuggestion = page.getByText('invalid-mention');
    await expect(mentionSuggestion).not.toBeVisible();

    // Action: Attempt to submit with invalid mention
    await submitButton.click();

    // Verification: Error message is displayed
    const errorMessage = page.getByText('Invalid mention format');
    await expect(errorMessage).toBeVisible();

    // Verification: Comment is not posted
    const postedComment = page.getByText('Hey @invalid-mention');
    await expect(postedComment).not.toBeVisible();

    // Action: Clear input and verify error clears
    await commentInput.clear();
    await expect(errorMessage).not.toBeVisible();

    // Action: Submit valid comment
    await commentInput.fill('This is a valid comment.');
    await submitButton.click();

    // Verification: Valid comment is posted
    const validComment = page.getByText('This is a valid comment.');
    await expect(validComment).toBeVisible();
  });
});
